void firBlock(const float* x, float* y, size_t n,
              const float* h, size_t L) {
    for (size_t i = 0; i < n; ++i) {
        float acc = 0.0f;
        for (size_t k = 0; k < L && k <= i; ++k)
            acc += h[k] * x[i - k];
        y[i] = acc;
    }
}

