class Fir {
    std::vector<float> h_, d_;   // d_ has 2L entries
    size_t L_, pos_ = 0;
public:
    explicit Fir(std::vector<float> h)
        : h_(std::move(h)), d_(2 * h_.size(), 0.0f), L_(h_.size()) {}

    void process(const float* x, float* y, size_t n) {
        for (size_t i = 0; i < n; ++i) {
            pos_ = (pos_ == 0) ? L_ - 1 : pos_ - 1;
            d_[pos_] = d_[pos_ + L_] = x[i];   // mirrored write
            const float* w = &d_[pos_];        // w[k] == x[n-k]
            float acc = 0.0f;
            for (size_t k = 0; k < L_; ++k) acc += h_[k] * w[k];
            y[i] = acc;
        }
    }
};
// requires L >= 1

