#include <cstddef>
#include <utility>
#include <vector>

class FirDecimator {
    std::vector<float> h_, d_;            // d_: mirrored delay line, 2L
    size_t L_, M_, pos_ = 0, phase_ = 0;  // phase_ survives between calls
public:
    FirDecimator(std::vector<float> h, size_t M)
        : h_(std::move(h)), d_(2 * h_.size(), 0.0f), L_(h_.size()), M_(M) {}

    // writes at most n / M + 1 outputs to y, returns how many
    size_t process(const float* x, size_t n, float* y) {
        size_t out = 0;
        for (size_t i = 0; i < n; ++i) {
            pos_ = (pos_ == 0) ? L_ - 1 : pos_ - 1;
            d_[pos_] = d_[pos_ + L_] = x[i];
            if (phase_ == 0) {                 // only kept outputs cost MACs
                const float* w = &d_[pos_];    // w[k] == x[n-k]
                float acc = 0.0f;
                for (size_t k = 0; k < L_; ++k) acc += h_[k] * w[k];
                y[out++] = acc;
            }
            phase_ = (phase_ + 1 == M_) ? 0 : phase_ + 1;
        }
        return out;
    }
};
